INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('R02', 'detailed', 'Страшно езеро', 'Рила', 'Планиран', 'Висока', 12, 850, 850, '', '', '', '', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+Malyovitsa', 'https://avtogari.info/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Мальовица (ЦПШ/х. Мальовица) → Йончево езеро → заслон Страшно езеро → х. Мечит → Говедарци', 'ДОБРО — данни в приложението съвпадат с туристически описания; опасният катерачен участък наличен в описанията.', '{"summary":"Достъп с автобус/шатъл до Мальовица; връщане/изход Говедарци с автобус/влак до/от София; местни таксита възможни.","car":{"available":true,"text":"Кола до паркингите при ЦПШ Мальовица и при Говедарци; пътищата са асфалтови до селото, после черни пътища в лоши условия.","parkingNote":"Паркинг при ЦПШ Мальовица и в Говедарци (GPS около 42.139,23.270; 42.192,23.180)."},"public":{"steps":[{"from":"София","to":"Мальовица/Bоровец shuttle","mode":"Автобус/микробус","time":"сезонно","note":"Проверете организиран транспорт през уикенда."},{"from":"Говедарци","to":"София","mode":"Автобус/влак (през Дупница)","time":"~1-1.5ч","note":"От Говедарци има редовни връзки към Дупница и София."}]}}'::jsonb, '[{"name":"заслон Страшно езеро","elevation":2391,"beds":null,"officialPhone":"112 / 1470 (ПСС)","altPhone":null,"email":null,"gps":"42.205,23.236 (прибл.)","verified":true,"conflict":"Заслонът е описван основно в пътеописите; липсват официални публикувани индивидуални телефони (ПСС номера за спешни случаи са дадени)."},{"name":"х. Мечит","elevation":2389,"beds":null,"officialPhone":"0886 225 576","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Х. Мечит се споменава в пътеписите като стоп при слизане към Говедарци; детайлна контактна информация липсва/непотвърдена."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Има известен опасен катерачен участък между Йончево и Страшно езеро — описан в планинарски статии и пътеописи.","Терен: каменисти участъци и стръмни откоси; подхлъзвания и падания са възможни при мокро.","Сезонност: зимните месеци и преходни сезони повишават риска (лед/сняг)."],"conclusion":"Подходящ за опитни туристи или с водач; при лошо време да не се предприема."}'::jsonb, '[{"date":null,"label":"Мальовица → Йончево езеро → заслон Страшно езеро","type":"Преход","distance":"6-7 км","gain":"~600-850м","time":"4-6ч","stay":"заслон Страшно езеро/х. Мальовица при връщане","difficulty":"Висок"},{"date":null,"label":"заслон Страшно езеро → х. Мечит → Говедарци","type":"Преход/слизане","distance":"5-6 км","gain":"~0-200м","time":"3-5ч","stay":"Говедарци","difficulty":"Среден/Висок"}]'::jsonb, '[{"name":"Настаняване в Говедарци (къщи за гости)","location":"Говедарци","rating":null,"price":null,"note":"Няколко къщи за гости и малки хотели; проверете Booking/ местни обяви."}]'::jsonb, '[{"name":"Такси Говедарци/Дупница","phone":null,"note":"Местни таксита, номера да се проверят локално."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.205&lon=23.236', ''),
('R03', 'detailed', 'Езерният', 'Рила', 'Планиран', 'Средна', 17, 1200, 600, '', '', '', '', 'Април/Май – Октомври (висока планинска част през лятото)', 'https://www.google.com/search?q=windy+prognoza+Rilski+Ezera', 'https://avtogari.info/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Паничище (лифт/вход) → х. Рилски езера → х. Вада → Говедарци', 'ДОБРО — х. Рилски езера потвърдена с контакти; стойности съвпадат с базовите данни.', '{"summary":"Лесен достъп с лифт/автобус до/от Паничище; връзки към Говедарци и София с автобус/влак през Дупница.","car":{"available":true,"text":"Асфалт до Паничище (паркинг при лифта), после пешеходен подход; паркинг при Говедарци/Паничище.","parkingNote":"Паркинг при Паничище (GPS ~42.178,23.331) е удобен за ранни изходи; в сезона може да е запълнен."},"public":{"steps":[{"from":"София","to":"Паничище","mode":"Автобус/лифт до Боровец/Паничище","time":"~1-1.5ч","note":"Лифтът/шатълите в сезони опростяват изкачването."},{"from":"Говедарци","to":"София","mode":"Автобус/влак","time":"~1-1.5ч","note":"Проверете автобусни връзки и разписания."}]}}'::jsonb, '[{"name":"х. Рилски езера","elevation":2115,"beds":null,"officialPhone":"088 551 0509","altPhone":"0886 509 409","email":"holidays@rilasport.com","gps":"42.220224,23.320543","verified":true,"conflict":null},{"name":"х. Вада","elevation":1640,"beds":null,"officialPhone":"0888 234 170","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Информация за х. Вада е оскъдна в публичните бази; остава непотвърдена."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: добри маркирани пътеки, но стръмни участъци при Рилски езера.","Инциденти: типични при лошо време — хипотермия, изпускане на маркировки; по-рядко технически проблеми.","Сезонност: зимни условия затрудняват преминаването; лятото е безопасно при нормална подготовка."],"conclusion":"Подходящ за хора с добра физическа подготовка и опит в дълги преходи."}'::jsonb, '[{"date":null,"label":"Паничище → х. Рилски езера","type":"Преход","distance":"8-9 км","gain":"~900-1200м","time":"4-6ч","stay":"х. Рилски езера","difficulty":"Среден"},{"date":null,"label":"х. Рилски езера → х. Вада → Говедарци","type":"Преход/слизане","distance":"8-9 км","gain":"~0-300м","time":"4-6ч","stay":"Говедарци","difficulty":"Среден"}]'::jsonb, '[{"name":"Хотели/къщи в Паничище/Боровец","location":"Паничище/Боровец","rating":null,"price":null,"note":"Много опции за нощувка в началната точка; удобна опция за петъчна нощувка."}]'::jsonb, '[{"name":"Такси Паничище/Говедарци","phone":null,"note":"Местни таксита — номера се проверяват локално."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.220224&lon=23.320543', ''),
('R04', 'detailed', 'Дивата Рила', 'Рила', 'Планиран', 'Висока', 22, 1200, 1200, '', '', '', '', 'Юни – Септември', 'https://www.google.com/search?q=windy+prognoza+Govedartsi', 'https://avtogari.info/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Говедарци → х. Рибни езера → маршрути през билата/пътеки → слизане към Рилски манастир', 'УМЕРЕНО — х. Рибни езера съществува и е свързана с Rilski ezera/форумни описания, но детайли за легла/контакти варират.', '{"summary":"Достъп до Говедарци с автобус/кола; крайна точка Рилски манастир с обществени връзки и таксита.","car":{"available":true,"text":"Асфалт до Говедарци и до Рилски манастир; при добри пътища и наличност на паркинг в началната/крайната точка.","parkingNote":"Паркинг в Говедарци и при Рилски манастир; туристически паркинг при манастира е платен в сезона."},"public":{"steps":[{"from":"София","to":"Говедарци","mode":"Автобус/влак+автобус","time":"~1.5ч","note":"Проверете връзките през Дупница."},{"from":"Рилски манастир","to":"София","mode":"Автобус/влак","time":"~1.5-2ч","note":"Добри връзки към Дупница и София."}]}}'::jsonb, '[{"name":"х. Рибни езера","elevation":2100,"beds":null,"officialPhone":"0898 718 205","altPhone":"0886 509 409","email":null,"gps":null,"verified":true,"conflict":"Хижата се свързва с регионалната хижарска мрежа; контакти често са свързани с х. Рилски езера (същите номера), което създава потенциална неяснота."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Дълъг преход с голяма денивелация; умора и ориентация са основни рискове.","Терен: диви, по-малко поддържани пътеки в някои участъци; възможни стръмни слизания.","Сезонност: ранна пролет и късна есен увеличават риска от сняг и леден настил."],"conclusion":"Подходящ за добре подготвени и навигиращи групи; планирайте резервации и възможни трансфери."}'::jsonb, '[{"date":null,"label":"Говедарци → х. Рибни езера","type":"Преход","distance":"10-12 км","gain":"~600-1200м","time":"5-8ч","stay":"х. Рибни езера","difficulty":"Висок"},{"date":null,"label":"х. Рибни езера → Рилски манастир","type":"Преход/слизане","distance":"10-12 км","gain":"~0-600м","time":"5-7ч","stay":"Рилски манастир","difficulty":"Среден/Висок"}]'::jsonb, '[{"name":"Настаняване при Рилски манастир","location":"Рилски манастир","rating":null,"price":null,"note":"Хотели и къщи за гости в района; резервации лесни през онлайн платформи."}]'::jsonb, '[{"name":"Такси Рилски манастир/Говедарци","phone":null,"note":"Местни номера се проверяват локално."}]'::jsonb, '', '')
